-- Module 2 — Call Fundamentals
insert into training_modules (id, vertical, category, ord, title, icon, capability_label, summary) values
  ('d2100002-0000-0000-0000-000000000002', 'dental', 'training', 2, 'Call Fundamentals', '👋', 'Opening, Name & Closing', 'Master the SIA Dental introduction, how to use the patient''s name, and how to close every call cleanly.');

