insert into training_modules (id, vertical, category, ord, title, icon, capability_label, summary) values
  ('d2100003-0000-0000-0000-000000000003', 'dental', 'training', 3, 'The Booking Conversation', '📅', 'Price, Close & Urgency', 'Handle the price question confidently, close with the double-option technique, and create natural urgency.');

