insert into training_modules (id, vertical, category, ord, title, icon, capability_label, summary) values
  ('d2100004-0000-0000-0000-000000000004', 'dental', 'training', 4, 'Objection Handling & Follow-Ups', '💬', 'Price, Nerves & Permission', 'Handle the three most common objections, guide anxious patients with confidence, and master the follow-up call.');

-- Module 5 — Complex Enquiries
insert into training_modules (id, vertical, category, ord, title, icon, capability_label, summary) values
  ('d2100005-0000-0000-0000-000000000005', 'dental', 'training', 5, 'Complex Enquiries', '🧩', 'Health Funds, Comparisons & Emergencies', 'Handle health fund questions confidently, stand out when patients are comparing practices, and respond to emergency calls with the right priority.');

-- Module 6 — Emergencies — Triaging
insert into training_modules (id, vertical, category, ord, title, icon, capability_label, summary) values
  ('d2100006-0000-0000-0000-000000000006', 'dental', 'training', 6, 'Emergencies — Triaging', '🚨', 'Assess urgency, book the right slot, know when to escalate', 'Emergency calls are the most time-critical calls you will ever take. This module teaches you how to quickly assess what type of emergency a patient has, ask the six triage questions, choose the correct booking outcome, and recognise the rare situations that require an immediate 000 call.');

-- Module 7 — Outbound Recall Calls
insert into training_modules (id, vertical, category, ord, title, icon, capability_label, summary) values
  ('d2100007-0000-0000-0000-000000000007', 'dental', 'training', 7, 'Outbound Recall Calls', '🔔', 'Re-activating Overdue Patients', 'Learn how to open an unexpected outbound call, handle the most common recall objections, and convert overdue patients into booked appointments.');

-- Module 8 — Open Treatment Plan Follow-ups
insert into training_modules (id, vertical, category, ord, title, icon, capability_label, summary) values
  ('d2100008-0000-0000-0000-000000000008', 'dental', 'training', 8, 'Open Treatment Plan Follow-ups', '📋', 'Closing Outstanding Treatment Cases', 'Learn how to follow up patients who agreed to treatment but never booked, identify the real reason they''re delaying, and help them commit without feeling pressured.');

-- Module 9 — Outbound Calls v2.0 — Price Guide Downloads
insert into training_modules (id, vertical, category, ord, title, icon, capability_label, summary) values
  ('d2100009-0000-0000-0000-000000000009', 'dental', 'training', 9, 'Outbound Calls v2.0 — Price Guide Downloads', '💰', 'Converting curious downloaders into booked patients', 'Master outbound calls to patients who downloaded SIA Dental''s price guide. These are warm leads — high-intent prospects who raised their hand. Your job is to convert their curiosity into a booking.');

-- Module 10 — Open Treatment Plan Calls — Advanced Practice
insert into training_modules (id, vertical, category, ord, title, icon, capability_label, summary) values
  ('d2100010-0000-0000-0000-000000000010', 'dental', 'training', 10, 'Open Treatment Plan Calls — Advanced Practice', '🎯', 'Prepare, Investigate, and Never Lose a Patient', 'Master the art of the open treatment plan call — the highest-converting outbound call type. Learn why these calls matter more than any other, how to prepare thoroughly before dialling, how to uncover the real reason a patient is stalling, and how to persist with compassion until you either book the patient or lock in a firm follow-up. Three hard practice scenarios.');

-- Module 11 — Handing Over to Another Dentist
insert into training_modules (id, vertical, category, ord, title, icon, capability_label, summary) values
  ('d2100011-0000-0000-0000-000000000011', 'dental', 'training', 11, 'Handing Over to Another Dentist', '🤝', 'Endorsement, Continuity & Handling Change', 'Dentists come and go — they relocate, change careers, or move on for personal reasons, and new dentists join in their place. When that happens, patients booked with a departing dentist need to be confidently handed over to someone new. This module teaches you how to endorse the new dentist, reassure patients that nothing is lost, and handle the resistance to change that nearly every one of these calls will bring. (The dentist names used in these practice calls are just examples — don''t get attached to them; the point is the rebooking skill itself.)');

-- Module 12 — Practice Turnaround — Reactivating an Acquired Patient Base
insert into training_modules (id, vertical, category, ord, title, icon, capability_label, summary) values
  ('d2100012-0000-0000-0000-000000000012', 'dental', 'training', 12, 'Practice Turnaround — Reactivating an Acquired Patient Base', '♻️', 'Rebuilding Trust from Near-Zero in a Newly-Acquired Practice', 'When a practice changes ownership, the existing patient base is a valuable but neglected asset — full of overdue recalls and half-finished treatment plans. Reactivating it is one of the most important things reception does in the first months. But these calls are unlike a normal recall: the patient doesn''t know you, may not recognise the practice, and is often wary. This module teaches you how to establish legitimacy fast, handle suspicion and the change of ownership, win back patients who left unhappy, and reconnect stale treatment plans — all without an existing relationship to lean on.');

-- ── Module content (Learn sections, rendered as markdown) ──────────────────
insert into module_sections (module_id, ord, heading, body) values
  ('d2100001-0000-0000-0000-000000000001', 1, 'The Real Cost of a Missed Call', 'When a patient calls and you miss that call — or handle it badly — it is not just a lost appointment. The average SIA Dental patient is worth $400–$600 per visit, visiting 2–3 times per year, across a 10–20 year relationship. That is $8,000–$36,000 of lifetime value walking out the door. The phone is SIA Dental''s highest-converting touchpoint. Unlike a website form or an online booking, a live call gives you the chance to listen, respond, and convert. Handle it well and you win a patient for life. Handle it poorly and they call the next practice on the list.'),
  ('d2100001-0000-0000-0000-000000000001', 2, 'Key Takeaways — The Real Cost', '- A missed $400 appointment = $8,000+ in lost lifetime patient value
- The phone converts better than any other channel — it''s live and personal
- Every call is a chance to build a long-term patient relationship'),
  ('d2100001-0000-0000-0000-000000000001', 3, 'One Goal, Every Time', 'Every call has one primary goal: a booking. Not ''answering questions.'' Not ''being helpful.'' A booking — or a rescheduled booking. This sounds obvious, but most receptionists drift into information-giving mode without ever moving toward a booking. The patient asks a question, you answer it, they say ''thanks'' and hang up. Call over. No booking. Staying focused on the goal does not mean being pushy — it means being purposeful. Answer the question, then immediately create a path to a booking: ''That''s our checkup and clean — when would suit you to come in?'''),
  ('d2100001-0000-0000-0000-000000000001', 4, 'Follow-Ups: Secondary But Critical', 'Sometimes a patient genuinely cannot book right now. That is fine — but never let them go without asking permission to follow up. ''Would it be okay if I called you Thursday to check in?'' Then actually call on Thursday. This one behaviour converts more undecided patients than anything else. Most practices do not follow up. The ones that do stand out immediately. It also signals to the patient that you care, which builds trust before they have even set foot in the practice.'),
  ('d2100001-0000-0000-0000-000000000001', 5, 'The Mindset Shift', 'Consider the difference between two approaches: ''How can I help you today?'' versus ''How can I book you in today?'' The words are almost identical — but the intent is completely different. One is reactive and open-ended. The other is purposeful and outcome-focused. Both approaches can be warm, empathetic, and patient-centred. But only one moves consistently toward a booking. This is the mindset shift that separates average receptionists from outstanding ones.'),
  ('d2100001-0000-0000-0000-000000000001', 6, 'Key Takeaways — Mindset & Follow-Ups', '- Primary goal: a booking. Everything else supports this goal, not replaces it.
- Ask permission before following up: ''Would it be okay if I called you Thursday?''
- Then actually call. Most practices don''t — this is your edge.
- ''How can I book you in?'' beats ''How can I help?'' — same warmth, clearer intent'),
  ('d2100002-0000-0000-0000-000000000002', 1, 'The First 10 Seconds', 'Research consistently shows that patients form their first impression of a practice within the first 10 seconds of a call. Answer within 3 rings — waiting longer immediately signals that the practice is disorganised or doesn''t value their time. Before you pick up, take one breath and smile. This sounds strange in a phone context, but smiling genuinely changes your vocal tone in a way that is audible and measurable. You will sound warmer, more engaged, and more professional before you have said a single word.'),
  ('d2100002-0000-0000-0000-000000000002', 2, 'The SIA Dental Introduction Formula', 'Every call, every time, without exception: ''Thank you for calling SIA Dental [Essendon / Burwood / Mulgrave], this is [your name] — how can I help you today?'' This formula does three things: it confirms the patient called the right place, it puts a name to the voice (making the conversation personal), and it opens with a question that invites them to explain their need. Memorise this. Vary the tone — never the words. When receptionists ad-lib the opening, they often start with ''Hi, SIA Dental'' which sounds informal and doesn''t include their name or the site.'),
  ('d2100002-0000-0000-0000-000000000002', 3, 'Key Takeaways — Opening', '- Answer within 3 rings — patience on hold signals disorganisation
- Smile before picking up — it changes your vocal tone audibly
- Exact formula: ''Thank you for calling SIA Dental [site], this is [your name] — how can I help you today?''
- Include the site name. Include your name. Every time.'),
  ('d2100002-0000-0000-0000-000000000002', 4, 'Getting the Name — and Using It', 'Ask for the patient''s first name within the first 30 seconds of the call. You can do this naturally as part of the booking process: ''Can I get your name to check our availability?'' or ''And who am I speaking with?'' Once you have their name, use it 2–3 times throughout the conversation — naturally, not mechanically. ''Absolutely, Sarah'' sounds very different from ''absolutely.'' It creates a sense of connection and genuine attention. Using someone''s name signals that you are talking to them specifically, not just whoever called.'),
  ('d2100002-0000-0000-0000-000000000002', 5, 'Ending Every Call Cleanly', 'A clean call close does two things: it confirms there is nothing else needed, and it leaves the patient with a warm, professional feeling about SIA Dental. The formula: ''Is there anything else I can help you with?'' — pause, let them answer — then: ''Wonderful. Thank you so much for calling SIA Dental — we look forward to seeing you.'' Do not rush this. The last thing a patient hears is what they remember. A rushed or abrupt goodbye undoes a lot of the goodwill built in the call.'),
  ('d2100002-0000-0000-0000-000000000002', 6, 'Key Takeaways — Name & Close', '- Ask for first name within 30 seconds: ''And who am I speaking with?''
- Use the name 2–3 times: naturally, not robotically
- Close: ''Is there anything else I can help you with?'' then ''Thank you for calling SIA Dental — we look forward to seeing you.''
- Never rush the goodbye — the last impression matters'),
  ('d2100003-0000-0000-0000-000000000003', 1, 'The Price Question Pivot', 'When a patient asks ''How much is a checkup?'', they are almost never just asking about price. They are evaluating whether SIA Dental is worth their time and money. If you simply quote a number — ''$280'' — you have given them something to react to without any context. Instead, anchor value first, then price: ''Our checkup and clean is $280 — that includes a full oral examination with X-rays if needed, a professional scale and clean, and a fluoride treatment applied in the chair. When would suit you to come in?'' Same price. Completely different conversation.'),
  ('d2100003-0000-0000-0000-000000000003', 2, 'Key Takeaways — Price', '- Never lead with a number — lead with value, then price
- Formula: ''[Price] — that includes [value items]. When would suit you?''
- Move immediately to a booking after answering the price question — do not wait for them to ask'),
  ('d2100003-0000-0000-0000-000000000003', 3, 'The Double Option Close', 'The single most powerful booking technique is the double option close. Never ask ''Would you like to make a booking?'' — that is a yes/no question that invites ''no'' or ''I''ll think about it.'' Instead, offer two specific times: ''We have Tuesday at 10am or Thursday at 2pm — which suits better?'' This shifts the decision from whether to book to when to book. The patient is choosing between two options you have already pre-qualified as available. Even if neither time works, the conversation has moved forward: ''Neither of those work for me'' → ''No problem, what day of the week generally works best for you?'''),
  ('d2100003-0000-0000-0000-000000000003', 4, 'Creating Urgency Naturally', 'Urgency does not mean pressure. It means giving the patient honest information that helps them decide now rather than later. ''We do get quite booked out, especially [day/time]'' is true — and it is relevant information for someone deciding when to book. ''I can hold that spot for you right now if you''d like'' removes friction and creates a small sense of scarcity. Done with warmth, this is excellent service. The patient does not want to miss out on a good appointment time — you are helping them, not pressuring them.'),
  ('d2100003-0000-0000-0000-000000000003', 5, 'Handling ''I''ll Think About It''', 'When a patient says ''I''ll think about it,'' they are usually signalling one of three things: they have a concern they haven''t voiced, the timing isn''t right, or they need a slightly stronger reason to commit. Your response: ''Of course — can I ask what''s holding you back? I want to make sure I''ve given you all the information.'' Then address whatever they raise. Then close again with the double option. Do not panic or accept it passively. Most ''I''ll think about it'' responses can be converted with one follow-up question.'),
  ('d2100003-0000-0000-0000-000000000003', 6, 'Key Takeaways — Close & Urgency', '- Double option close: ''We have Tuesday at 10 or Thursday at 2 — which suits better?''
- Never ask ''Would you like to book?'' — it''s a yes/no question that invites ''no''
- Urgency: ''We do get quite booked out — I can hold that spot for you right now''
- ''I''ll think about it'' → ''Of course — can I ask what''s holding you back?'''),
  ('d2100004-0000-0000-0000-000000000004', 1, 'The Three Most Common Objections', 'Most incoming call objections fall into three categories: Price (''It seems expensive''), Time (''I''m too busy''), and Fear (''I''m a bit nervous''). Each requires a different response, but all three share one principle: acknowledge before you pivot. Never argue, never justify defensively, and never launch into a sales pitch before acknowledging what the patient said. ''I completely understand'' buys you 30 seconds of goodwill and a patient who feels heard. Then address the specific concern, then move back toward the booking.'),
  ('d2100004-0000-0000-0000-000000000004', 2, 'Key Takeaways — The Three Objections', '- Price: ''I understand — let me walk you through what''s included in that price...'' then pivot to value
- Time: ''We have early morning and Saturday appointments available — when does your schedule open up?''
- Fear: ''I completely understand — a lot of our patients feel the same way before their first visit...'' then name the dentist
- Always acknowledge before pivoting — never argue or justify'),
  ('d2100004-0000-0000-0000-000000000004', 3, 'The Nervous Patient Pathway', 'Anxious patients need to feel understood and safe before they will commit to a booking. The pathway is: Acknowledge → Normalise → Personalise with a dentist → Close. Acknowledge: ''I completely understand — it''s more common than you''d think.'' Normalise: ''A lot of our patients feel the same way before their first visit — and they''re always surprised by how comfortable it is.'' Personalise: ''Dr [Name] is genuinely wonderful with patients who feel nervous. She takes her time, explains everything, and makes sure you''re comfortable before any treatment starts.'' Then close: ''She has availability on Thursday at 11 — would that work for you?'' Name the dentist. Always name the dentist.'),
  ('d2100004-0000-0000-0000-000000000004', 4, 'Follow-Up with Permission — Every Time', 'Before ending any call where a booking was not made, ask: ''Would it be okay if I followed up with you on [specific day]?'' Note the day in your system. Call on that day. This is not aggressive sales — it is professional follow-through that most businesses never do. Patients who initially said ''I''ll think about it'' are frequently converted on the follow-up call, simply because you called when you said you would. It signals reliability, care, and the kind of attention that makes a patient want to be treated at SIA Dental.'),
  ('d2100004-0000-0000-0000-000000000004', 5, 'What Never to Do', 'There are four things to avoid with every objection. Do not argue price — it creates defensiveness and positions you as adversarial. Do not justify yourself — ''Well our prices are fair because...'' sounds insecure. Do not let silence pressure you into over-explaining — one clear response followed by a question is always stronger than a long speech. And do not accept a passive ''I''ll think about it'' without one follow-up question. One question: ''Can I ask what''s holding you back?'' is the difference between a converted patient and a lost one.'),
  ('d2100004-0000-0000-0000-000000000004', 6, 'Key Takeaways — Follow-Up & What Not to Do', '- The nervous patient pathway: Acknowledge → Normalise → Name the dentist → Close
- Always name the dentist with a specific warm description matching their concern
- Ask for follow-up permission: ''Would it be okay if I called you Thursday?''
- Never argue price, never over-explain, never accept ''I''ll think about it'' without one follow-up question'),
  ('d2100005-0000-0000-0000-000000000005', 1, 'Health Fund Questions', 'SIA Dental accepts all major health funds — Bupa, Medibank, HCF, NIB, Defence Health, and others. There are two very different questions a patient might ask, and you need to handle them differently.

The easy one: ''Do you accept [fund]?'' — the answer is always yes. Lead with confidence: ''Yes, absolutely — we accept [fund]. Can I book you in?''

The trickier one: ''Are you a preferred provider for [fund]?'' — this is where you need to know your site. Preferred provider status by site: Essendon is NIB and HCF. Burwood is NIB, HCF, Defence Health, and CBHS. Mulgrave is NIB, Defence Health, and CBHS. Bupa and Medibank are not preferred providers at any site — but we accept them everywhere and see many happy patients on both funds.

When you ARE a preferred provider: ''Great news — yes, we are a [fund] preferred provider here at [site]. That means you get your maximum rebates with us. Can I book you in?''

When you are NOT a preferred provider (including all Bupa and Medibank enquiries): ''We''re not a preferred provider for [fund], but we have many happy [fund] patients here who find the gap is very manageable — and the real benefit is you get to keep seeing the same dentist every visit rather than starting over with someone new. Can I book you in?''

The most important thing: never be apologetic about not being a preferred provider. Validate the patient — they are making a smart choice coming to SIA Dental — then move to booking.'),
  ('d2100005-0000-0000-0000-000000000005', 2, 'Key Takeaways — Health Funds', '- SIA Dental accepts ALL major health funds — always answer yes with confidence
- Know your site''s preferred providers: Essendon = NIB + HCF, Burwood = NIB + HCF + Defence Health + CBHS, Mulgrave = NIB + Defence Health + CBHS
- Bupa and Medibank: not preferred at any site — validate with ''many happy patients, manageable gap, continuity of care''
- When you ARE a preferred provider — lead with the good news: ''Great news — yes, we are!''
- Never be apologetic. Reframe, validate, then close: ''Can I book you in?'''),
  ('d2100005-0000-0000-0000-000000000005', 3, 'Emergency Calls — Lead with Empathy', 'Emergency calls require a completely different opening. The patient is in pain — sometimes severe pain. Before you say anything about availability, costs, or logistics, you lead with empathy. ''I''m so sorry you''re in pain — let''s get you in as soon as possible.'' This one sentence changes the entire dynamic of the call. The patient feels heard and prioritised, which means they stay on the line and stay calm. Then: check same-day availability, confirm the booking, and before you hang up — plant the seed: ''Once this is all sorted, we''d love to have you come back for a full checkup — you''re now a patient of the practice.'''),
  ('d2100005-0000-0000-0000-000000000005', 4, 'Comparing Practices — Tell a Story', 'When a patient is comparing practices, they are not looking for a features list. Every practice has ''experienced dentists'' and ''state-of-the-art equipment.'' What cuts through is a specific story: a dentist quality, a patient experience, a technology differentiator. ''Dr Edmund Kwong at our Essendon site has been doing this for over 15 years — patients travel from interstate to see him.'' Or: ''We do all our crown work in-house using same-day CEREC technology — no temporary crowns, no second appointment.'' Then create urgency: ''We do get booked up — can I hold you a spot? Very easy to cancel if you change your mind.'' Make the decision easy to start.'),
  ('d2100005-0000-0000-0000-000000000005', 5, 'Child First Visits', 'A parent calling for a child''s first dental visit is often more anxious than the child. Mirror the parent''s anxiety back with empathy — ''I completely understand, a lot of parents feel that way.'' Then paint a specific picture of what the visit looks like: ''Dr [Name] is wonderful with little ones — she takes it really slowly, shows them all the tools first so nothing is a surprise, and makes the whole thing feel like an adventure rather than a dental visit.'' Use the child''s name if you know it. Paint a vivid, reassuring picture. Book them before they overthink it.'),
  ('d2100005-0000-0000-0000-000000000005', 6, 'Key Takeaways — Complex Calls', '- Emergency calls: ''I''m so sorry you''re in pain — let''s get you in as soon as possible.'' Lead with empathy, always.
- Comparing practices: tell one specific story, then create urgency: ''Can I hold you a spot?''
- Child first visits: use the child''s name, name the dentist, paint a picture of the experience
- Health fund: acknowledge the truth, reframe as continuity of care, then close'),
  ('d2100006-0000-0000-0000-000000000006', 1, 'Why Emergency Triage Is Your Job', 'When a patient calls with an emergency, your triage decision on that call determines whether someone with a spreading infection waits three days or gets seen today. A knocked-out tooth needs re-implanting within 30 minutes — every minute you spend on unnecessary questions is a minute closer to that window closing. A patient with swelling spreading toward their throat may need emergency services, not a dental appointment.

This is not just scheduling. It is clinical decision-making at the front desk. Done well, it protects patients from worsening injuries and infections, protects the dentist’s schedule from wrong appointment lengths, and protects the practice from complaints. The good news: it is a learnable skill. You need six questions and four outcomes.'),
  ('d2100006-0000-0000-0000-000000000006', 2, 'The 6 Triage Questions — Ask Every Time', '- Pain rating 1–10: anything 7 or above is almost certainly same-day
- Where exactly: specific tooth, spreading to jaw, neck, or under the eye?
- How long: hours = acute and urgent; days or weeks may be chronic, not crisis
- Character of pain: throbbing or aching = likely infection; sharp on biting or cold = crack or nerve
- Any swelling: cheek = urgent same-day; spreading to jaw, neck, or throat = possible 000
- Tooth history: previous root canal, crown, old filling, untreated decay, recently broken?'),
  ('d2100006-0000-0000-0000-000000000006', 3, 'Emergency Types — What You Will Hear and What to Do', 'Toothache: Pain 7–10 or throbbing overnight — book same-day and flag as emergency in D4W. Pain 4–6 with no swelling — book within 48 hours.

Facial swelling or suspected abscess: Any visible facial swelling — book same-day and notify the dentist before the patient arrives. Swelling spreading to the neck or throat — tell the patient to call 000 before coming in.

Broken or chipped tooth: Pain or sharp edge — book same-day. Cosmetic chip only with no pain — book within 48 hours.

Knocked-out tooth: TIME CRITICAL. Give survival instructions immediately: put the tooth back in the socket gently, or keep it in milk. Come in right now — you have roughly 30 minutes. Do not try to re-implant baby teeth — just come in and have it checked.

Lost filling or crown: Sensitivity and exposed tooth — book within 48 hours; block 45–60 minutes for assessment and a temporary restoration.

Post-op pain or bleeding: Mild ache after an extraction is normal. Heavy bleeding not stopping after firm gauze pressure for 20 minutes — call the dentist immediately, and advise the patient to call 000 if they feel faint or bleeding does not slow.

Dental abscess with visible pus: Bad taste, visible pus, or a sinus tract — book same-day. The dentist may need to prescribe antibiotics.

Sensitivity only: No acute pain, no swelling — this is not an emergency. Book a standard 60-minute examination appointment.'),
  ('d2100006-0000-0000-0000-000000000006', 4, 'Four Booking Outcomes — Every Emergency Fits One', '- Same-day (ASAP): Pain 7–10, any visible swelling, broken tooth with pain, knocked-out tooth, active uncontrolled post-op bleeding
- Within 48 hours: Pain 4–6 with no swelling, lost filling or crown causing sensitivity, known abscess not spreading
- Longer appointment (60 min+): Sensitivity only with no acute pain, complex multi-tooth assessment needed, lost crown requiring impressions
- Call 000 or go to ED: Swelling to neck or throat, cannot breathe or swallow, unresponsive patient, uncontrolled bleeding after 20 minutes of pressure'),
  ('d2100006-0000-0000-0000-000000000006', 5, 'When to Call 000 — Non-Negotiable Triggers', '- Swelling spreading to the neck, throat, under the eye, or floor of the mouth
- Patient cannot breathe or swallow properly
- Patient feels faint, dizzy, or reports chest pain
- Heavy bleeding not stopping after 20 minutes of firm continuous pressure
- Any sign of severe allergic reaction: widespread hives, throat tightening, known allergy to medication
- Script: ‘I need to stop you there — please call 000 right now and tell them it is a dental emergency with swelling near your throat. Go straight to hospital, do not wait.’'),
  ('d2100006-0000-0000-0000-000000000006', 6, 'Triaging Without Interrogating — Language and Tone', 'Emergency patients are frightened or in pain. Do not fire six questions at them the moment they finish their opening line. Lead with empathy every time: ‘I am so sorry you are going through this — let us get you sorted right away.’ Then weave your triage questions naturally through the conversation.

For a knocked-out tooth, give survival instructions before you take any details — every minute matters. ‘Put the tooth back in the socket if you can, or drop it in a glass of milk. Come straight to us now — what is the closest site to you?’ Get the site, then book, then take their name.

After every emergency booking, add a short note in D4W before the patient arrives: ‘Emergency — suspected abscess, lower left jaw, 2 days, swelling visible.’ This lets the dentist prepare instruments and walk in ready. It takes ten seconds and it matters.

For uncertain post-op situations, do not guess. Tell the patient: ‘Let me check with the dentist quickly while I have you on the line.’ A 60-second hold is far better than the wrong advice.'),
  ('d2100007-0000-0000-0000-000000000007', 1, 'Why Patients Stop Coming Back', 'Most patients who drift away from a practice are not unhappy — they are just busy. Life gets in the way, the gap grows, and the longer it goes the more awkward it feels to come back. A small number are deterred by cost or a past experience. Understanding the reason behind the drift changes how you approach the call. Your job is not to chase a patient — it is to make it easy and low-pressure for them to return to something they already know is good for their health.'),
  ('d2100007-0000-0000-0000-000000000007', 2, 'Key Takeaways — Why Patients Drift', '- Most drift is passive (busy, forgot) — not a decision to leave
- The longer the gap, the more awkward it feels to return — your warmth fixes this
- Common real reasons: cost anxiety, fear of what they''ll find, new job location
- Your tone in the first 10 seconds determines whether they stay on the call'),
  ('d2100007-0000-0000-0000-000000000007', 3, 'The 3-Step Outbound Opening Formula', 'On an outbound recall call, you are interrupting someone''s day. The first 15 seconds are critical. Step 1 — Identify yourself and the practice clearly: ''Hi, is this [Name]? This is [Your Name] calling from SIA Dental.'' Step 2 — Give a warm, non-alarming reason for the call: ''I''m just calling because we noticed you''re due for your routine check and clean, and we wanted to reach out personally.'' Step 3 — Immediately invite rather than pressure: ''We''d love to get you back in when the timing works for you.'' This approach is friendly, honest, and opens the door without demanding anything.'),
  ('d2100007-0000-0000-0000-000000000007', 4, 'Key Takeaways — The Opening Formula', '- Step 1: Name yourself and the practice immediately — never leave them guessing who''s calling
- Step 2: Give a warm reason, not an alarm — ''just following up on your recall'' not ''you''re overdue''
- Step 3: Invite, don''t demand — ''we''d love to get you back in'' feels very different from ''you need to book''
- Match their energy — if they sound rushed, keep it brief; if they''re chatty, build rapport'),
  ('d2100007-0000-0000-0000-000000000007', 5, 'Handling ''I''ll Call You Back When I''m Ready''', 'This is the most common recall objection — and the most dangerous if you accept it passively. The patient is not rejecting you; they are deferring commitment. Your response: acknowledge first, then offer a specific, easy alternative. ''Of course — no pressure at all. Can I ask, is there a time of year that generally works better for you? We could put a reminder in our system and reach out then.'' This keeps you in control of the next touchpoint instead of waiting for a call that will never come. If they say ''just next month'', offer to call them in 3 weeks. Make the follow-up concrete.'),
  ('d2100007-0000-0000-0000-000000000007', 6, 'Reframing the Call as Care, Not Sales', 'Patients can sense when a call is about filling a schedule versus genuinely caring about their health. The language you use matters. Instead of: ''We just wanted to fill some gaps in our schedule this week'' — say: ''We do a personal reach-out to patients who are due, because catching things early is always better for you.'' Instead of: ''It''s been a while since we''ve seen you'' — say: ''We just want to make sure your teeth are looked after.'' The difference is subtle but powerful. One feels transactional; the other feels like a practice that actually cares about its patients.'),
  ('d2100007-0000-0000-0000-000000000007', 7, 'Key Takeaways — Language That Works', '- Never say ''you''re overdue'' — say ''you''re due for your recall, and we wanted to reach out personally''
- Never blame the gap — acknowledge it warmly: ''It''s been a while and that''s completely okay''
- ''I''ll call back'' → ''Of course — is there a better time of year? I can note it in our system''
- Frame every outbound call as a health check-in, not a booking push'),
  ('d2100008-0000-0000-0000-000000000008', 1, 'Why Treatment Plans Go Cold', 'When a patient leaves the practice with a treatment plan but no booking, they almost always intend to follow through. Life gets in the way. Cost concerns grow now that the immediate dental chair conversation is over. Fear re-emerges once they''re not being reassured by a calm clinician. The urgency fades once the tooth stops hurting. Understanding this helps you approach the follow-up with empathy rather than pressure — your job is to reconnect them with why they said yes in the first place, and to remove whatever is now blocking them.'),
  ('d2100008-0000-0000-0000-000000000008', 2, 'Key Takeaways — Why OTPs Go Cold', '- Most OTP patients still intend to book — they just haven''t yet
- The three blockers: cost, fear of the procedure, and fading urgency
- Your call reconnects them to the ''yes'' they already gave the dentist
- You are not selling new treatment — you are helping them follow through on a decision they already made'),
  ('d2100008-0000-0000-0000-000000000008', 3, 'Identifying the Real Blocker', 'The patient will rarely tell you the real reason upfront. They''ll say ''I''ve just been busy'' when the real reason is fear. They''ll say ''I need to check my schedule'' when the real reason is cost. Your job is to ask one gentle open question that surfaces the blocker: ''Is there anything you wanted to check or that I can answer before we get you booked in?'' This gives them permission to say what''s really holding them back without feeling embarrassed. Once you know the real blocker, you can address it directly and specifically.'),
  ('d2100008-0000-0000-0000-000000000008', 4, 'Key Takeaways — Finding the Blocker', '- Ask: ''Is there anything you wanted to check or I can help with before we get you booked?''
- ''Busy'' often means fear or cost — one open question surfaces the real objection
- Never assume the reason — ask, then address specifically
- Acknowledge the blocker before pivoting — never dismiss or minimise it'),
  ('d2100008-0000-0000-0000-000000000008', 5, 'Making It Easy to Say Yes', 'Once you know the blocker, your goal is to lower the barrier to booking. For fear: describe the procedure briefly and warmly — name the dentist and how they handle anxious patients. For cost: clarify the payment process, mention health fund contributions, or offer to break the treatment across two visits if clinically appropriate. For fading urgency: give an honest, non-scary clinical reason why acting now is better than waiting — ''Leaving a cracked tooth can sometimes lead to needing more complex work down the track, and the recovery is generally harder.'' Be honest and specific, not alarmist.'),
  ('d2100008-0000-0000-0000-000000000008', 6, 'The Language of Clinical Necessity vs Sales Pressure', 'There is a fine line between informing and pressuring. Patients can feel the difference immediately. Clinical necessity language sounds like: ''The dentist recommended this because...'' or ''The reason it''s worth doing sooner is...'' Sales pressure sounds like: ''This treatment is really important and you shouldn''t wait.'' The first builds trust. The second creates resistance. Always anchor your urgency in what the dentist said, not in your desire to fill the appointment. Reference the clinical recommendation. That is the authority in the room — not you.'),
  ('d2100008-0000-0000-0000-000000000008', 7, 'Key Takeaways — Language & Urgency', '- Anchor urgency in the clinical recommendation: ''The dentist flagged this because...''
- Never exaggerate risk — honest and specific is more trusted than alarming
- Fear blocker: name the dentist and describe how they handle the procedure for anxious patients
- Cost blocker: mention health fund, payment process, or spreading treatment across visits if possible
- Always close with two specific times — ''We have Tuesday at 11 or Thursday at 2 — which works better?'''),
  ('d2100009-0000-0000-0000-000000000009', 1, 'What the Price Guide Download Really Means', 'When a patient downloads SIA Dental''s price guide, they are not passively browsing — they are actively researching. Think about what that action requires: they found our website, decided we were worth investigating, and gave us their contact details in exchange for pricing information. That is not a casual gesture. These are patients who are in the research phase of a buying decision — they have a dental need, they are comparing options, and they are open to being helped.

The research phase is the best time to reach out. Before they have made a decision. Before they have booked elsewhere. Before their interest fades. A patient who downloaded your price guide yesterday and hears from you today is far more likely to convert than one you contact next week. Speed and warmth are your two most important tools in this call type.'),
  ('d2100009-0000-0000-0000-000000000009', 2, 'Key Takeaways — What the Download Signals', '- Downloading the price guide is a high-intent signal — they are actively researching
- They already know our name and our prices — your call is the first human contact
- They are in the comparison phase — most have not yet booked elsewhere
- Speed matters: reach out within 24–48 hours while the intent is still warm
- They ticked their area of interest — use it to personalise the call'),
  ('d2100009-0000-0000-0000-000000000009', 3, 'The Mindset: Warm Outreach, Not Cold Calling', 'There is a crucial difference between a cold call and a warm call. A cold call interrupts someone who never asked to hear from you. A warm call is a follow-up to an action they took. When you call a price guide downloader, you are not cold calling — you are responding to them. They raised their hand first.

This changes everything about your tone. You are not apologising for interrupting them. You are not pushing a product they didn''t ask about. You are following up on something they started. Your job is to be the helpful, knowledgeable person who makes it easy to take the next step they were already thinking about.

The mindset to carry into every call: ''This person is interested. My job is to make the next step feel easy.'' That''s it. Not to sell. Not to close at all costs. To make it easy.'),
  ('d2100009-0000-0000-0000-000000000009', 4, 'Opening the Call — The First 20 Seconds', 'Your opening must do three things: identify who you are, why you''re calling, and make them feel this call is for them — not for you.

The formula: ''Hi, is this [Name]? This is [Your Name] calling from SIA Dental. I''m reaching out because you recently downloaded our price guide — I just wanted to personally check in to see if there''s anything I can help with, or any questions I can answer for you.''

Notice what this does. It identifies you immediately. It references the action they took — no mystery about why you''re calling. It is framed entirely around helping them, not booking them. And ''personally check in'' signals that this is not an automated marketing call — it''s a human being reaching out.

Never open with ''I''m calling to book you in'' — that sounds like a sales script. And note what they ticked: if they selected Cosmetic Dentistry, you have the perfect hook. ''I noticed you were interested in cosmetic treatments — I''d love to point you in the right direction.'''),
  ('d2100009-0000-0000-0000-000000000009', 5, 'The Three Patient Types You Will Encounter', 'Price guide callers tend to fall into three categories, and each requires a different approach.

The Cosmetic Dreamer — They ticked Cosmetic Dentistry (veneers, whitening, smile makeover). They have wanted this treatment for a while but keep putting it off. Price is a concern, but so is uncertainty about whether it''s right for them. They may have looked at other clinics. The goal: get them in for a cosmetic consultation where the dentist can show them what''s possible for their specific case. You are not selling veneers — you are selling a conversation that might change everything.

The Budget Dental Shopper — They ticked general dental (fillings, checkups, general treatment). They are price-sensitive and cautious. They may say ''I''m just looking'' or ''I''ll call back when I''m ready.'' The goal: reframe the appointment as low-risk and low-cost, create just enough urgency to get them in before the issue worsens.

The Quote Comparer — They ticked multiple areas and may already have a written quote from a competitor. They are analytical and methodical. Do not compete on price — you will lose. Instead, sell the assessment: every mouth is different, a quote without examination is just an estimate, our dentist will give a personalised picture at no obligation. The goal: book them in for a consultation.'),
  ('d2100009-0000-0000-0000-000000000009', 6, 'Objection Handling — Price, Uncertainty, and Competition', 'Three objections will come up repeatedly on price guide calls.

''It''s too expensive.'' Do not defend the price. Do not compare it. Instead, separate the consultation from the treatment cost: ''The consultation itself is just [price] — it''s really about coming in and finding out what''s possible for your specific situation. A lot of patients are surprised by what we can achieve. Would you be open to coming in just to see what the options are?'' You are selling the appointment, not the treatment. The dentist sells the treatment.

''I''m not sure I''m ready / I''ll call back.'' This is a delaying signal. Acknowledge it, then gently surface the real concern: ''Completely understand — can I ask, is there anything specific you wanted more information about before deciding? I want to make sure you''ve got everything you need.'' Surface the concern. Address it. Then offer a specific low-commitment next step.

''I''ve already got a quote from [Clinic X].'' Do not try to undercut them. Do not criticise the other clinic. Validate and reframe: ''That''s really smart to do your research. The thing is, a quote without a proper examination is really just an estimate — every mouth is different. Our dentist can give you a personalised picture of your specific situation, and that''s completely obligation-free. You might find the two quotes are actually quite different once the dentist has had a proper look.'' The win is not a price war — it''s a consultation.'),
  ('d2100009-0000-0000-0000-000000000009', 7, 'Key Takeaways — The Close', '- You are selling the appointment, not the treatment — the dentist sells the treatment
- Price objection: ''The consultation is just [price] — come in and see what''s possible for your specific situation''
- ''Not ready'': ask what''s holding them back, then address it, then offer a specific low-commitment next step
- Competitor quote: validate their research, then reframe — ''a quote without examination is just an estimate''
- Always close with two specific times: ''We have Tuesday at 10 or Thursday at 2 — which suits better?''
- Every call goal: get them into the chair for the dentist to see them'),
  ('d2100010-0000-0000-0000-000000000010', 1, 'Why OTP Calls Are Your Highest-Value Work', 'When a patient leaves the practice with a treatment plan but no booking, a clock starts ticking. Every week that passes, the urgency fades, the dental issue remains unresolved, and the likelihood of the patient returning without a prompt drops significantly. An open treatment plan is not a missed sale — it is a patient who has a documented clinical need, or a genuine desire for cosmetic improvement, that simply has not yet been acted on.

Consider what it took to generate that treatment plan: the patient found SIA Dental, made an appointment, came in, sat in the chair, had a clinical examination, heard the dentist''s recommendations, and left. All of that groundwork is already done. The investment — from the practice and from the patient — has already been made. An OTP follow-up call is not starting a conversation from scratch. It is picking up a thread that was already in motion.

When you convert an OTP patient, you are not just filling a schedule. You are helping someone with a real dental issue — a crack that could escalate to an extraction, an infection that antibiotics are only temporarily masking, a cosmetic concern that has quietly affected their confidence for years. These calls are good for the practice and genuinely good for the patient. Both things are true, and knowing that should change how you feel when you pick up the phone to make them.'),
  ('d2100010-0000-0000-0000-000000000010', 2, 'Key Takeaways — Why These Calls Matter', '- All the groundwork is done — the patient already said yes to investigating treatment
- Clinical OTP patients have real, documented needs. You are helping them, not selling to them.
- Cosmetic OTP patients have a desire they haven''t acted on — you are helping them navigate the decision
- Every unconverted OTP is a patient whose dental issue continues to go unresolved
- These are your highest-conversion calls because the patient is already warm — they just need a nudge'),
  ('d2100010-0000-0000-0000-000000000010', 3, 'The Pre-Call Preparation Ritual — Every Single Time', 'The single biggest difference between a good OTP call and a great one is what happens before you dial. Most receptionists pick up the phone knowing only the patient''s name and that they have an open treatment plan. That is not enough. Before every OTP call, open the patient''s file in D4W and confirm:

1. When they last came in (gives you a natural reference point: ''You came in back in March...'')
2. Which dentist they saw (you will name this dentist — make them real and specific)
3. What treatment was recommended — the exact procedure, and ideally the tooth number or area
4. The reason the dentist recommended it, if noted in the clinical record
5. Whether the patient has a health fund on file, and what fund it is

Walking into the call without this information is noticeable. When the patient asks ''Wait, which tooth are we talking about?'' and you cannot answer, you lose credibility. When you can say ''Dr Kwong recommended crowns on your lower left back teeth — that''s teeth 34 and 36'' without hesitation, the patient hears competence and care.

For clinical OTP calls, also mentally rehearse the one honest, non-alarmist clinical reason the dentist flagged. You do not need to recite the notes verbatim. You just need one specific, real reason: ''The reason Dr Kwong flagged it is that those teeth have quite large fillings, and if a crack develops, what''s currently a straightforward crown can become something more involved.'' That one sentence, delivered calmly, does more work than any amount of urgency language.

For cosmetic OTP calls, think about what the patient was excited about at the consultation. Was it a special occasion? A long-standing insecurity about their smile? A specific look they showed the dentist? That motivation is still there — it just got buried under time and second-guessing. Your job is to reconnect them to it.'),
  ('d2100010-0000-0000-0000-000000000010', 4, 'Pre-Call Checklist — Open D4W Before You Dial', '- Date of last visit — reference it naturally in your opening
- Dentist''s name — you will use it. Know how to describe their style briefly.
- Exact treatment recommended — procedure name, tooth if relevant
- The clinical reason, in one plain-language sentence
- Health fund on file — know before you offer cost reassurance
- For cosmetic calls: what was their original motivation?'),
  ('d2100010-0000-0000-0000-000000000010', 5, 'Clinical Need vs Cosmetic — Two Very Different Conversations', 'Not all OTP calls have the same emotional texture, and treating them the same is a mistake.

Clinical need calls (crowns, root canals, fillings, extractions, implants) carry genuine health stakes. The patient often knows they need this done — they agreed with the dentist in the chair. What has changed is that the pain faded, the bill felt larger outside the clinic, or life got in the way. For these calls, you have a legitimate, honest tool: the clinical consequence of inaction. A cracked tooth left untreated can eventually need extraction instead of a crown. A root canal deferred while on antibiotics will likely re-infect when the antibiotics are gone. These are not scare tactics — they are real clinical risks, and sharing them is doing the patient a genuine service. Anchor every urgency claim in what the dentist recommended, not in your desire to fill a slot. The dentist''s authority is in the room, even on a phone call.

Cosmetic calls (veneers, whitening, Invisalign, smile consultations) are fundamentally different. There is no health urgency. The patient has a desire — for confidence, for a specific look, for a goal they have been putting off. Inventing clinical urgency here will feel manipulative and will lose the patient. Instead, your tool is reconnecting them to their original motivation. ''When you came in, was there a particular occasion you had in mind, or something that prompted it?'' When a patient articulates their own reason for wanting something, they sell themselves far better than you can sell it to them. Then address the specific concern holding them back, and offer the lowest-commitment next step that still gets them back in the chair — often a short follow-up consultation rather than booking the full treatment.'),
  ('d2100010-0000-0000-0000-000000000010', 6, 'Key Takeaways — Clinical vs Cosmetic', '- Clinical calls: you have a genuine clinical reason — use it honestly, anchor it in what the dentist said
- Cosmetic calls: there is no clinical urgency — do not invent it. Reconnect to the patient''s own motivation instead.
- For clinical: ''The reason Dr [X] flagged this is...'' — one specific, plain-language sentence
- For cosmetic: ''When you came in, what originally prompted you to look into this?'' — let them sell themselves
- Cosmetic goal: get them back for a follow-up consultation, not necessarily the full treatment booking'),
  ('d2100010-0000-0000-0000-000000000010', 7, 'Digging Into the Real Blocker', 'The surface reason a patient gives for not booking is almost never the real reason. ''I''ve just been busy'' means something else. ''I need to check my schedule'' means something else. Your job in every OTP call is to ask one gentle, open question that gives the patient permission to tell you what is actually holding them back:

''Is there anything you wanted to check or that I can help with before we get you booked in?''

This question works because it does not presuppose anything. It is not ''Is the cost the issue?'' or ''Are you nervous about the procedure?'' — both of which feel presumptuous. It simply opens a door. And when patients walk through that door, they usually tell you exactly what you need to know.

The three real blockers, and how to address each:

Cost: ''I''m just not sure what the gap will be after my health fund.'' Address it directly: know their fund before you call, give a rough guide if you can, offer to check on their behalf, or at minimum schedule an appointment to come in and get the exact figures before committing. The gap is often less alarming once someone actually checks.

Fear: ''I''ve been a bit nervous about the procedure, to be honest.'' This is your cue to name the dentist with a specific, warm, relevant description — not generic reassurance like ''it won''t hurt.'' Specific: ''Dr Kwong is really methodical about this — he walks you through each step before he does it, and you can signal to stop at any point if you need a moment. Patients who are nervous beforehand are usually surprised by how comfortable it actually is.''

Fading urgency: ''It''s not really hurting anymore, so...'' This is where the clinical reality lands: antibiotics treat the infection temporarily, not the underlying issue. A crack does not heal on its own. Be honest, brief, and specific — and then move to a booking before they have time to re-rationalise.'),
  ('d2100010-0000-0000-0000-000000000010', 8, 'Call Scripts That Work — Practical Examples', 'Here are three examples of what the opening of a well-prepared OTP call sounds like:

Example 1 — Crown Follow-Up:
''Hi, is this Jane? Hi Jane, it''s [your name] calling from SIA Dental Essendon. I''m just following up on your visit with Dr Kwong back in March — he recommended those two crowns on your lower left back teeth. How have those been feeling? [...] That''s good to hear. Is there anything you wanted to check or that I could help with before we got that booked in? [...] That''s really common — Medibank patients find the gap is usually quite manageable for crown work. Can I look into that for you right now while we''re on the phone? [...] The main thing Dr Kwong was flagging is that both teeth have quite large old fillings, and over time there''s a real risk one of them cracks — at that point a crown becomes a more complicated job. We have Tuesday at 11 or Thursday at 2 — which tends to suit you better?''

Example 2 — Veneer Consultation Follow-Up:
''Hi, is this Amanda? Hi Amanda, it''s [your name] from SIA Dental. I''m just following up on your cosmetic consultation with Dr Tan a couple of months back — she mentioned you were thinking about the veneers. [...] Totally understandable — can I ask what''s been holding you back? [...] That''s such a valid concern — the ''fake look'' is exactly what Dr Tan works hardest to avoid. She actually designs each veneer individually to match the shape and shade of your natural teeth, so the people around you notice you look better but can''t quite explain why. Would it help to come back in for a quick follow-up — just to see some examples from similar cases and ask her anything else you''re wondering about? It''s a short appointment, no commitment at all.''

Example 3 — The Won''t-Commit Follow-Up (see below).'),
  ('d2100010-0000-0000-0000-000000000010', 9, 'The Patient Who Won''t Commit — Persistence and the 2-Week Rule', 'Some patients will not book on the call. Not because you said the wrong thing, not because the practice has done anything wrong — but because they are genuinely not ready to commit right now. When you hit this wall, there are two mistakes to avoid:

Mistake 1 — Giving up too early. One objection is not the end. If the patient says ''I''ll think about it,'' you have room for at least two more angles before you accept defeat. Address the specific concern they raised. Try a different angle. Offer a later appointment date — sometimes ''we have something in 3 weeks'' removes the pressure of immediacy. Name the dentist personally. Try framing the clinical risk once more, calmly. You should make at least 3 genuine attempts before accepting that this patient is not booking today.

Mistake 2 — Letting them go without a next step. This is the costly one. If a patient absolutely will not commit to a booking after multiple attempts, the call is not over until you have locked in a specific follow-up date. Not ''I''ll call you again sometime.'' A specific date: ''No problem at all — would it be okay if I gave you a quick call in two weeks, say Thursday the 19th around 10am, just to check in?'' Then note it in D4W before you move on. This patient does not get lost in the system.

SIA Dental''s standard on OTP patients is this: every patient either books, or is on the follow-up list with a specific next contact date. Neither option is acceptable without the other being in place.

When a patient eventually comes in and gets the treatment they needed — and you were the person who kept following up — that is worth more than any single booking. Patients notice when a practice cares enough not to drop them.'),
  ('d2100010-0000-0000-0000-000000000010', 10, 'The 2-Week Rule — Never Lose a Patient', '- Try at least 3 angles before accepting ''not today'' — address the specific objection each time
- If they won''t commit: ''Would it be okay if I called you back in 2 weeks — say Thursday the 19th at 10am?''
- Log the follow-up in D4W before moving on — a verbal note is not enough
- SIA standard: every OTP patient either has a booking or a specific next follow-up date
- Persistence is not pressure — it is the level of care that sets SIA Dental apart from every other practice that gave up after one call'),
  ('d2100010-0000-0000-0000-000000000010', 11, 'About This Module''s Practice Calls', 'The three practice calls in this module are harder than anything in previous modules. Each one gives you a patient file brief before you dial — this is the pre-call preparation you should do before every real OTP call. Read it, absorb it, and use it.

Call 1 — Jane Doe: Two crown recommendations on lower back teeth. A patient who already said yes at the consultation but hasn''t followed up. The real blocker is cost — she''s not sure what her health fund covers. You need to remove that barrier.

Call 2 — Amanda Chen: A veneer quote from 8 weeks ago. No clinical urgency. She went home, did her research, and got nervous about results looking fake. Your job is to reconnect her to her original motivation and address the concern directly. A low-commitment follow-up consultation is a win here.

Call 3 — Michael Torres: Root canal required. Antibiotics have cleared the pain. He feels fine and has no urgency. This patient is scripted NOT to commit to a booking — no matter what you try, he will defer. Your score on this call is based on two things: how hard and how persistently you tried, and whether you ended the call with a specific follow-up date locked in. Letting him hang up without a next step is the failure mode to avoid.'),
  ('d2100011-0000-0000-0000-000000000011', 1, 'Why Dentist Handovers Happen — and Why They Matter', 'A dental practice is a living thing. Over the years, dentists move on — they relocate, change careers, take parental leave, or simply move to another stage of life. New dentists join to take their place. This is completely normal and healthy, but it creates a delicate moment for every patient who had a relationship with the departing dentist.

There are two situations you will face. The ideal one is a warm, planned handover: the departing dentist personally introduces their patients to the dentist taking over, and you simply confirm the new arrangement. The far more common reality is messier — the dentist has already left, and you are calling patients who have appointments booked with someone who is no longer here, trying to move them across to a new dentist.

This second situation is where the skill lives. Every one of these calls is a moment where a loyal, long-term patient could quietly slip away — not because anything is wrong, but because their dentist is gone and change feels like a reason to leave. Handled well, the patient barely feels the disruption and stays with the practice for another decade. Handled poorly, you lose a patient worth tens of thousands in lifetime value over a single phone call.'),
  ('d2100011-0000-0000-0000-000000000011', 2, 'Key Takeaways — Why Handovers Matter', '- Dentists leaving and joining is normal — the risk is in how the patient experiences it
- Ideal: a warm personal handover from the departing dentist. Common: you''re calling after they''ve gone.
- Every handover call is a retention moment — a loyal patient could quietly leave
- The goal: the patient barely feels the disruption and stays with the practice'),
  ('d2100011-0000-0000-0000-000000000011', 3, 'Patients Fear Change, Not the New Dentist', 'When a patient resists being moved to a new dentist, they are almost never reacting to the new dentist — they have never met them. They are reacting to the loss of something familiar. They built trust with ''their'' dentist over years: that dentist knows their history, their nervousness, their mouth. Starting again with a stranger feels like starting from zero.

Understanding this changes how you handle the call. You are not selling a new dentist — you are protecting a relationship the patient already has with the practice, and transferring the trust they had in one clinician onto another.

The single biggest mistake on a handover call is giving the patient an easy exit. ''Would you like me to cancel that for now and you can call back when you''re ready?'' feels polite and helpful — but it hands the patient the door. They will take it, and they will not call back. Never offer to cancel. Instead, assume continuity: the appointment is still happening, just with a wonderful new dentist, and your job is to make that feel like the obvious, easy choice.'),
  ('d2100011-0000-0000-0000-000000000011', 4, 'Key Takeaways — Change, Not the Dentist', '- The resistance is about losing the familiar — not about the new dentist, whom they haven''t met
- Your job: transfer the trust from the old dentist onto the new one
- NEVER offer to cancel or say ''call back when you''re ready'' — that hands them the exit
- Assume continuity: the appointment stands, just with a great new dentist'),
  ('d2100011-0000-0000-0000-000000000011', 5, 'The Endorsement — Make the New Dentist Real', 'The endorsement is the heart of every handover call. Saying ''Dr [New] can see you instead'' does nothing — it''s a substitution, not a reassurance. A real endorsement bridges the trust the patient already has across to the new dentist.

The pattern is: Acknowledge the relationship → Reassure continuity → Endorse with specifics. First, acknowledge what the patient is losing: ''I know you''ve always seen Dr [Old], and you''ve been in great hands with him.'' Then reassure that nothing is actually lost: ''The good news is your full history and records carry straight across — whoever you see will know exactly where you''re up to.'' Then endorse the new dentist warmly and specifically: ''Dr [New] has actually taken over Dr [Old]''s patients — she''s lovely, very gentle, takes her time, and patients who were nervous about the change have been really happy with her.''

Notice what makes this work: it is specific, not generic. ''She''s really good'' means nothing. ''She''s very gentle and takes her time'' paints a picture. The new dentist inherits the trust the patient had — they don''t have to earn it from scratch — because you handed it to them.'),
  ('d2100011-0000-0000-0000-000000000011', 6, 'Recall vs Open Treatment Plan Handovers', 'Handover calls come in two flavours, and they carry different risks.

A RECALL handover is a routine check-up and clean that was booked with the departing dentist. The stakes feel low to the patient — it''s ''just a clean'' — which is exactly why the cancellation risk is high. There''s no urgent reason in their mind to keep it, so if you give them any wobble room they''ll defer indefinitely. Your tools here are warmth, a confident endorsement, and keeping the booking firmly on the table.

An OPEN TREATMENT PLAN handover is more delicate. The departing dentist diagnosed something — a crown, a filling, a root canal — and the patient agreed to it but hadn''t yet booked. Two specific objections appear here. First: ''I''ll just wait until Dr [Old] is back'' — but Dr [Old] isn''t coming back, so you must redirect honestly rather than let that sit. Second: ''Won''t a new dentist just want to start all over again?'' This is the key fear with treatment plans, and the answer is your strongest card: the new dentist has the existing plan, notes and X-rays, and continues exactly where things were left — no re-examination, no re-doing diagnostics, no paying twice. Reassuring that continuity is what unlocks the booking.'),
  ('d2100011-0000-0000-0000-000000000011', 7, 'The Handover Call Structure', '- Open warmly, introduce yourself and the practice — they weren''t expecting the call
- Be honest the dentist has moved on — keep it simple, positive and private
- Acknowledge the patient''s relationship with their original dentist before pivoting
- Reassure continuity: history, records (and any treatment plan) all carry across
- Endorse the new dentist specifically and warmly — bridge the trust
- Assume the booking — confirm it with the new dentist; never offer to cancel'),
  ('d2100011-0000-0000-0000-000000000011', 8, 'What Never to Do', 'There are five things that lose patients on a handover call.

Never offer to cancel. ''Shall I cancel that for now?'' is the single most damaging line — it gives a hesitant patient permission to leave, and they will.

Never bad-mouth or over-explain why the dentist left. The reason is private and rarely helps. ''Dr [Old] has moved on from the practice'' is enough. Don''t speculate, don''t gossip, don''t get defensive if the patient probes — keep it simple, positive, and redirect to continuity.

Never make the patient feel like a problem being reassigned. ''We need to move you to someone else'' sounds administrative and cold. Frame it as the practice taking care of them: ''I wanted to personally make sure you''re looked after.''

Never leave it vague. ''Someone will see you'' or ''one of our other dentists'' gives the patient nobody to trust. Always name the new dentist and make them real.

Never let ''I''ll wait until Dr [Old] is back'' go unchallenged when that dentist is not returning. Letting it sit is dishonest and guarantees the patient drifts. Gently and warmly redirect to the new dentist every time.'),
  ('d2100011-0000-0000-0000-000000000011', 9, 'Key Takeaways — What Never to Do', '- Never offer to cancel — it''s the line that loses the patient
- Never bad-mouth or over-explain the departure — ''has moved on'' is enough; keep it positive and private
- Never make the patient feel reassigned — frame it as the practice caring for them
- Never be vague — always name the new dentist and make them real
- Never let ''I''ll wait until they''re back'' stand when the dentist isn''t returning — redirect warmly'),
  ('d2100012-0000-0000-0000-000000000012', 1, 'What a Practice Turnaround Actually Is', 'When a practice is bought or taken over, it comes with a database of patients — but many of them have drifted. Recalls went un-chased, treatment plans were never followed up, and the previous owner may have let the patient experience slip in the run-up to selling. That database is one of the most valuable assets the new owners have bought, but only if those patients can be brought back. Reactivating them is a core part of reception''s job in the first months under new ownership.

The maths is powerful. A lapsed patient is far cheaper to bring back than a brand-new patient is to win — they already chose this practice once, and their records (however thin) already exist. Bring a few back each week and you steadily rebuild a healthy, full appointment book. Most of these calls are recalls (overdue check-ups) and open treatment plans (recommended work that was never completed). The skills you''ve learned in those modules all apply — but with one crucial difference that changes everything about how the call opens.'),
  ('d2100012-0000-0000-0000-000000000012', 2, 'Key Takeaways — The Turnaround Opportunity', '- An acquired patient base is a bought asset — neglected, but valuable if reactivated
- Lapsed patients are cheaper to bring back than new patients are to win
- Most reactivation calls are overdue recalls and unfinished treatment plans
- The skills are familiar — but the trust context is completely different'),
  ('d2100012-0000-0000-0000-000000000012', 3, 'Why These Calls Are Different from a Normal Recall', 'A normal recall call rests on an existing relationship — the patient knows the practice, knows their dentist, and trusts the place. A turnaround reactivation call has none of that. The patient hasn''t been in for years, may not recognise the practice''s current name, doesn''t know you, and doesn''t know the dentists. From their side, an unfamiliar practice is suddenly phoning them out of the blue.

That means you start from near-zero trust — sometimes from suspicion. Before a single word about booking, your job is to make the patient feel that this call is legitimate, relevant, and worth their time. You cannot lean on ''you''re due for your check-up'' the way an established practice can, because the patient doesn''t yet accept that this is ''their'' practice. Everything in this module is about rebuilding that trust quickly and honestly, so the familiar recall and treatment-plan skills can actually land.'),
  ('d2100012-0000-0000-0000-000000000012', 4, 'Establishing Legitimacy in the First 15 Seconds', 'Because the patient doesn''t recognise you, your opening has to do more work than any other call type. It must answer four unspoken questions immediately: Who are you? Which practice? Why are you calling me? And why should I care? Get these out clearly and warmly before anything else, or the patient''s guard stays up.

A strong opening sounds like: ''Hi, is this [Name]? My name is [Your Name], I''m calling from [Practice] on [Street/Area] — you may remember us, you were a patient with us a while back. I''m part of the new team here, and I''m personally reaching out to patients we haven''t seen in a while just to check in and make sure you''re looked after.'' Notice what this does: it names you, names and locates the practice (jogging their memory), explains the call honestly, and frames it as care, not sales. What you must avoid is sounding like a telemarketer — no mystery, no rushing, no launching into an offer. Slow, clear, and human beats fast and scripted every time on these calls.'),
  ('d2100012-0000-0000-0000-000000000012', 5, 'Key Takeaways — Opening the Call', '- Answer four questions fast: who are you, which practice, why calling, why care
- Locate the practice (street/area) to jog a hazy memory
- Frame it as a personal check-in from the new team — care, not sales
- Never sound like a telemarketer: no mystery, no rush, no instant offer
- Slow, clear and human beats fast and scripted on a cold-trust call'),
  ('d2100012-0000-0000-0000-000000000012', 6, 'Handling Suspicion & ''What Happened to My Old Dentist?''', 'Two questions come up constantly on these calls: some version of ''Who is this and how did you get my number?'' and ''What happened to the old place / Dr [X]?'' Both are trust tests, and both are won with calm transparency.

For suspicion, simply be open: ''You were a patient here previously, so you''re in our records — I''m just reaching out personally, there''s nothing to worry about.'' Honesty disarms suspicion far better than deflection.

For the ownership change, be straightforward and positive — and keep it brief: ''The practice actually came under new ownership recently. The new owners have reinvested in the place, and we''re reaching out to existing patients to welcome them back.'' The golden rule: never bad-mouth the previous owner or dentist. Even if the patient left unhappy, criticising the old practice makes you look unprofessional and makes the patient wonder what you''ll say about them later. Keep the previous owner''s exit simple, positive and private, and pivot to what''s genuinely better now — fresh investment, more availability, more time per patient.'),
  ('d2100012-0000-0000-0000-000000000012', 7, 'Winning Back the ''I Left for a Reason'' Patient', 'Some patients drifted by accident; others left on purpose — a bad experience, feeling rushed, long waits, no follow-up. When a patient says ''I stopped going there for a reason,'' how you respond in the next ten seconds decides the call.

The instinct to defend the practice is the wrong one. Defensiveness confirms their fear that nothing has changed. Instead, acknowledge genuinely first: ''I''m really sorry to hear that was your experience — that''s exactly the kind of thing the new team is determined to put right.'' Then differentiate the new ownership as a real, concrete change — not a vague promise: more time per patient, new equipment, a genuine focus on the experience that was missing before. Then make a low-pressure invitation: ''I''d love the chance to show you it''s genuinely different now — even just a proper check-up to start fresh.'' You are not arguing that the past was fine. You are giving them a credible reason to believe the present is different. Over-promising or dismissing their experience both lose the patient.'),
  ('d2100012-0000-0000-0000-000000000012', 8, 'Reactivating Stale Recalls & OTPs Without Continuity', 'Many reactivation calls involve old, unfinished treatment plans — work a previous dentist recommended that was never completed. Here you face a problem the OTP modules didn''t: the diagnosing dentist has often left, and the records are thin. You do not have the full picture, and pretending you do will get you caught out the moment the patient asks a detail you can''t answer.

Honesty is the strategy. Reconnect them to the fact that there was unfinished treatment — ''Our records show some work was started a while back that was never completed'' — but be upfront that the right next step is a fresh look rather than blindly resuming an old plan: ''Quite a bit of time has passed and the dentist who saw you then has moved on, so the sensible thing is a fresh assessment to see where things are now — no obligation to go ahead with anything.'' This is honest, it''s clinically sound, and it gets the patient back in the chair, which is the goal. And because you can''t personally vouch for a dentist you don''t know well yet, endorse on credentials and approach rather than invented familiarity: ''Dr [New] is excellent and really thorough — she''ll take the time to go through everything properly with you.'''),
  ('d2100012-0000-0000-0000-000000000012', 9, 'The Turnaround Call Structure', '- Open with full, warm self-identification — who, which practice, why, why care
- Disarm suspicion with honest transparency, not deflection
- Explain the new ownership simply and positively — never trash the previous owner
- If they left unhappy: acknowledge genuinely, then differentiate what''s truly different now
- For stale plans: be honest about limited continuity; offer a fresh assessment as the reset
- Endorse the new dentist on credentials + a fresh start, not personal familiarity
- Aim for one low-pressure next step — usually a comprehensive check-up'),
  ('d2100012-0000-0000-0000-000000000012', 10, 'What Never to Do', 'Five things lose patients on a turnaround call.

Never bad-mouth the previous owner or dentist. It looks unprofessional and makes the patient distrust you.

Never pretend you know the patient or their history better than you do. The records are thin — claiming deep familiarity gets exposed the moment they ask a specific question, and exposure destroys the fragile trust you''ve built.

Never be pushy with a wary patient. On a cold-trust call, pressure reads as a scam or a hard sell and ends the call. Earn the trust first; the booking follows.

Never be vague about who you are or why you''re calling. Mystery is the fastest way to get hung up on — patients assume the worst about unidentified callers.

Never leave a reactivated patient with a soft, open-ended ending. ''Give us a call if you ever want to come in'' loses them. Once you''ve rebuilt enough trust, guide them to a specific next step — a fresh check-up — the same way you would on any recall.'),
  ('d2100012-0000-0000-0000-000000000012', 11, 'Key Takeaways — What Never to Do', '- Never bad-mouth the previous owner — it makes the patient distrust you
- Never fake familiarity you don''t have — thin records get exposed fast
- Never push a wary patient — pressure reads as a scam; earn trust first
- Never be vague about who you are — mystery gets you hung up on
- Never end soft — once trust is rebuilt, guide them to a specific next step');

-- ── Quizzes (options stored as a JSON array; correct = 0-based index) ──────
insert into quiz_questions (module_id, ord, question, options, correct, explanation) values
  ('d2100001-0000-0000-0000-000000000001', 1, 'What is the primary goal of every incoming call at SIA Dental?', '["To answer the patient''s questions fully and completely", "To make the patient feel welcome and cared for", "To secure a booking or rescheduled appointment", "To explain the services and pricing at SIA Dental"]'::jsonb, 2, 'The primary goal is always a booking. Answering questions and making patients feel welcome are important — but they are means to the end, not the end itself.'),
  ('d2100001-0000-0000-0000-000000000001', 2, 'A patient calls, asks about checkup pricing, you give a clear answer, they say ''Thanks, I''ll think about it'' and hang up. What went wrong?', '["The price was too high", "You answered the question but never moved toward booking them in", "You should have told them to book online instead", "Nothing — you did your job by answering their question"]'::jsonb, 1, 'You answered the question but drifted into information-giving mode. After answering, always pivot: ''That''s our checkup and clean — when would suit you to come in?'' Always move toward the booking.'),
  ('d2100001-0000-0000-0000-000000000001', 3, 'A patient says they cannot book today but are interested. What is the correct next step?', '["Thank them and end the call — they will call back when ready", "Give them the website address to book online", "Ask permission to follow up: ''Would it be okay if I called you Thursday?''", "Transfer them to the dentist to discuss further"]'::jsonb, 2, 'Always ask permission before following up — and then actually call. This one behaviour converts more undecided patients than anything else, and most practices don''t do it.'),
  ('d2100001-0000-0000-0000-000000000001', 4, 'Which of these counts as a successful call outcome?', '["The patient got all the information they asked for", "The patient said they would think about it and might call back", "The patient booked an appointment or agreed to a specific follow-up call", "The patient said you were very helpful and friendly"]'::jsonb, 2, 'A successful call ends with a booking or a clear committed next step (a specific follow-up time). Positive feedback and information exchange are good — but they are not the goal.'),
  ('d2100002-0000-0000-0000-000000000002', 1, 'What is the correct SIA Dental phone introduction?', '["Hi, SIA Dental, how can I help?", "Good morning, dental practice, what can I do for you?", "Thank you for calling SIA Dental [site], this is [your name] — how can I help you today?", "SIA Dental, please hold."]'::jsonb, 2, 'The full formula includes: ''Thank you for calling'', the site name, your name, and the opening question. All four elements serve a specific purpose and none should be dropped.'),
  ('d2100002-0000-0000-0000-000000000002', 2, 'When should you ask for the patient''s first name?', '["At the very end of the call when confirming the booking", "Only if they seem friendly — some patients find it intrusive", "Within the first 30 seconds, naturally as part of the conversation", "After you have explained all the pricing and availability"]'::jsonb, 2, 'Get the name early — within the first 30 seconds. It personalises the entire rest of the conversation. ''And who am I speaking with?'' works at almost any natural moment early in the call.'),
  ('d2100002-0000-0000-0000-000000000002', 3, 'How many times should you use the patient''s name during a typical call?', '["Just once at the start to confirm you heard it correctly", "As many times as possible — the more the better", "2–3 times, used naturally throughout the conversation", "Never — some patients find it overly familiar"]'::jsonb, 2, '2–3 times is the sweet spot. Once to confirm you heard it, once or twice during the conversation at natural moments like ''Absolutely, Sarah'' or ''Great choice, Sarah.'' Overuse feels scripted.'),
  ('d2100002-0000-0000-0000-000000000002', 4, 'What is the correct way to end a call?', '["''OK thanks, bye!'' — keep it quick and efficient", "''Is there anything else I can help you with?'' then ''Thank you for calling SIA Dental — we look forward to seeing you.''", "Ask for a Google review before hanging up", "Transfer to the dentist for a final confirmation"]'::jsonb, 1, 'Always check for anything else needed, then close warmly. The last impression is what patients remember — a clean, warm close reinforces the positive experience of the whole call.'),
  ('d2100003-0000-0000-0000-000000000003', 1, 'A patient asks ''How much is a checkup and clean?'' What is the correct response?', '["''It''s $280.'' — be direct and transparent about pricing", "''It varies depending on what the dentist finds.'' — manage expectations", "''Our checkup and clean is $280 — that includes a full exam, scale and clean, and fluoride treatment. When would suit you to come in?''", "''Let me transfer you to the dentist to discuss pricing.''"]'::jsonb, 2, 'Lead with value, then price, then immediately move toward a booking. Attaching the price to specific inclusions makes it feel like value rather than just a cost.'),
  ('d2100003-0000-0000-0000-000000000003', 2, 'Which is the correct way to offer booking options?', '["''Would you like to make a booking with us?''", "''Let me know when you''d like to come in and I''ll check availability.''", "''We have Tuesday at 10am or Thursday at 2pm — which suits better?''", "''I''ll put you on our waitlist and we''ll call you when something comes up.''"]'::jsonb, 2, 'The double option close gives two specific times and makes the question ''when'' not ''whether.'' It removes the chance for a yes/no answer and keeps the booking momentum going.'),
  ('d2100003-0000-0000-0000-000000000003', 3, 'What does natural urgency sound like?', '["''You need to book today or we won''t have anything for weeks.''", "''We do get quite booked out — I can hold that spot for you right now if you''d like.''", "''It''s completely up to you, no rush at all.''", "''We have plenty of availability — whenever works for you is fine.''"]'::jsonb, 1, 'Natural urgency is honest and helpful — not pressure. ''We get booked out'' is true. ''I can hold that spot right now'' removes friction. Together they create gentle motivation without feeling pushy.'),
  ('d2100003-0000-0000-0000-000000000003', 4, 'A patient says ''I''ll think about it.'' What is the correct response?', '["''Of course, take your time — give us a call when you''re ready!''", "''Okay, I''ll add you to our newsletter so you don''t miss any specials.''", "''Of course — can I ask what''s holding you back? I want to make sure I''ve given you all the information.''", "''I completely understand — shall I send you our price list by email?''"]'::jsonb, 2, '''I''ll think about it'' usually means there''s an unvoiced concern. One follow-up question — ''What''s holding you back?'' — surfaces it. Then address it, then close again. Most ''think about it'' calls can be converted.'),
  ('d2100004-0000-0000-0000-000000000004', 1, 'A nervous patient says ''I''m a bit anxious about dentists — I haven''t been in years.'' What is the correct first response?', '["''Don''t worry — our dentists are very good and it won''t hurt at all.''", "''I completely understand — a lot of our patients feel the same way before their first visit, and they''re always surprised by how comfortable it is.''", "''We offer sedation dentistry if that would help — would you like more information?''", "''That''s okay — we''ll go through your x-rays first so you know exactly what needs doing.''"]'::jsonb, 1, 'Acknowledge and normalise first. ''Don''t worry'' dismisses their concern. The correct response validates their feeling, normalises it, and opens the door to naming a specific dentist who is great with nervous patients.'),
  ('d2100004-0000-0000-0000-000000000004', 2, 'What is the correct follow-up permission language at the end of a call where no booking was made?', '["''We''ll add you to our recall list and contact you in 6 months.''", "''Feel free to call us back when you''re ready to book.''", "''Would it be okay if I followed up with you on Thursday?''", "''I''ll email you our price list so you can compare options at home.''"]'::jsonb, 2, 'Always ask permission before following up — with a specific day. Then actually call on that day. This one behaviour converts more undecided patients than anything else, and most practices never do it.'),
  ('d2100004-0000-0000-0000-000000000004', 3, 'A patient says ''Your price is higher than the practice down the road.'' What should you NOT do?', '["Acknowledge their concern before responding", "Explain what is included in the price that makes it good value", "Argue that the other practice is lower quality", "Name a specific dentist who delivers outstanding results"]'::jsonb, 2, 'Never argue price or disparage competitors — it sounds defensive and unprofessional. Acknowledge → pivot to value → name a dentist → close. Comparing yourself negatively to competitors creates distrust, not confidence.'),
  ('d2100004-0000-0000-0000-000000000004', 4, 'When should you name a specific dentist during a call?', '["Only if the patient specifically asks about a dentist", "Never — it''s better to let the patient choose after they arrive", "For anxious patients specifically — it is a core part of the nervous patient pathway", "Only when the patient is comparing practices with competitors"]'::jsonb, 2, 'Naming a specific dentist with a warm, relevant description is essential for anxious patients. It makes the dentist feel real and trustworthy before the patient has even met them — and it significantly increases booking conversion.'),
  ('d2100005-0000-0000-0000-000000000005', 1, 'A patient asks ''Are you a Bupa preferred provider?'' What is the correct response?', '["''Let me check that for you and call you back.''", "''No, unfortunately we''re not a Bupa preferred provider.''", "''We''re not a Bupa preferred provider, but we have many happy Bupa patients here who find the gap is very manageable — and the benefit is you get to keep seeing the same dentist every visit. Can I book you in?''", "''We accept Bupa — that should be fine.'' — avoid the preferred provider topic entirely"]'::jsonb, 2, 'SIA Dental is not a Bupa preferred provider at any site. The correct response acknowledges this directly, then immediately validates with reassurance (many happy patients, manageable gap) and reframes the benefit as continuity of care. Never be apologetic, never suggest they go elsewhere, and always close with a booking question.'),
  ('d2100005-0000-0000-0000-000000000005', 2, 'A patient calls with severe toothache. What is the correct opening response?', '["''Hi, SIA Dental — can I get your name and date of birth?''", "''We have a same-day appointment available at 2pm — does that work?''", "''I''m so sorry you''re in pain — let''s get you in as soon as possible.''", "''Emergency appointments are $150 — is that okay before we proceed?''"]'::jsonb, 2, 'Lead with empathy before logistics. The patient is in pain — hearing ''I''m so sorry you''re in pain'' first tells them they called the right place. Then move to same-day availability, then confirm the booking.'),
  ('d2100005-0000-0000-0000-000000000005', 3, 'A patient says they are calling several practices to compare. What is the best approach?', '["List all of SIA Dental''s services and explain the pricing clearly", "Tell them what makes SIA Dental unique versus other practices in the area", "Tell one specific story — a dentist quality or patient experience — then create urgency: ''Can I hold you a spot?''", "Offer to match any lower price they''ve been quoted"]'::jsonb, 2, 'A specific story cuts through where a features list doesn''t. Then make commitment easy with low friction: ''Can I hold you a spot? Easy to cancel if you change your mind.'' This gets the booking started while they still have momentum.'),
  ('d2100005-0000-0000-0000-000000000005', 4, 'A parent calls to book their 4-year-old''s first dental visit and sounds nervous. What is the best approach?', '["Explain that children''s dental visits are very quick and painless — there''s nothing to worry about", "Offer to email them information about what to expect at a first visit", "Mirror the parent''s anxiety with empathy, name a specific dentist who is great with children, paint a picture of the visit, and use the child''s name", "Suggest they bring the child in for a ''meet and greet'' before booking a full appointment"]'::jsonb, 2, 'The parent''s anxiety is real and valid. Acknowledge it, then make the dentist feel real and trustworthy with a specific description. Use the child''s name — it makes everything more personal. Paint a picture. Then book before they overthink it.'),
  ('d2100006-0000-0000-0000-000000000006', 1, 'A patient calls with 8 out of 10 pain, throbbing for 3 days, no visible swelling. What is the correct response?', '["Book a standard 30-minute appointment for later in the week", "Book same-day and flag it as a dental emergency in D4W", "Tell them to take painkillers and call back if it gets worse", "Ask them to send photos of the tooth before booking"]'::jsonb, 1, '8 out of 10 throbbing pain for 3 days almost certainly indicates a dental infection — it will not resolve without treatment and may worsen rapidly. Same-day booking is essential, and a D4W note helps the dentist prepare and prioritise.'),
  ('d2100006-0000-0000-0000-000000000006', 2, 'A patient tells you that swelling on their jaw has now spread to under their chin, and they are having difficulty swallowing. What do you do?', '["Book them same-day urgently and tell them to come in quickly", "Transfer them to the dentist for advice before booking", "Tell them to call 000 immediately — this is a medical emergency", "Take their details and call them back once the dentist is free"]'::jsonb, 2, 'Swelling spreading to the neck or throat with difficulty swallowing is a life-threatening emergency — potentially Ludwig’s angina. Do not attempt to book an appointment. Tell the patient to call 000 right now and go straight to hospital.'),
  ('d2100006-0000-0000-0000-000000000006', 3, 'A patient has just knocked out a front tooth playing sport 10 minutes ago. What is your FIRST action on the call?', '["Take their name and date of birth and book the next available slot", "Ask whether it is a baby tooth or an adult tooth before giving any advice", "Give immediate tooth-survival instructions and tell them to come in right now", "Tell them to go straight to the hospital emergency department"]'::jsonb, 2, 'A knocked-out tooth has a 30-minute re-implantation window. Your first action is to keep the tooth viable: back in the socket, or in milk. Tell them to come in immediately. Admin details come after. Time saved now directly improves the outcome.'),
  ('d2100006-0000-0000-0000-000000000006', 4, 'A patient reports mild cold sensitivity for two weeks — no acute pain, no swelling, no other symptoms. Which booking outcome is correct?', '["Same-day emergency slot — sensitivity can indicate something serious", "Standard 30-minute appointment at the next available slot", "A longer 60-minute appointment — thorough examination is needed", "Ask them to monitor and call back only if it gets worse"]'::jsonb, 2, 'Two weeks of sensitivity without acute pain is not an emergency, but it warrants a thorough examination — a crack, exposed root, or early decay can be missed in a short slot. Book a 60-minute appointment. Option D is not appropriate — dental issues rarely resolve without intervention.'),
  ('d2100007-0000-0000-0000-000000000007', 1, 'You are calling a patient who is 18 months overdue for their recall. How should you introduce yourself?', '["''Hi, this is SIA Dental — you''re quite overdue for your checkup and we need to get you booked in.''", "''Hi, is this [Name]? This is [Your Name] from SIA Dental. I''m just calling because you''re due for your routine check and clean, and we wanted to reach out personally.''", "''Hi, we noticed you haven''t been in for a while and wanted to check if everything is okay.''", "''Hi, do you have a minute? I''m calling from SIA Dental about your dental care.''"]'::jsonb, 1, 'Option B follows the 3-step formula: identify yourself and the practice, give a warm non-alarming reason, and frame it as a personal reach-out rather than a chase. Never lead with ''overdue'' — it sounds accusatory.'),
  ('d2100007-0000-0000-0000-000000000007', 2, 'A patient says ''Thanks for calling — I''ll ring you back when I''m ready to book.'' What is the correct response?', '["''Of course, take your time — our number is on our website whenever you''re ready.''", "''Sure — is there a time of year that works better for you? I can put a note in our system and follow up then.''", "''Actually, it would be great to book you in now — we have availability this week.''", "''Okay, no problem. Would you like me to send you a reminder text?''"]'::jsonb, 1, 'Accept their deferral gracefully, but keep control of the next touchpoint. Getting a specific future follow-up is far better than losing the conversation entirely. ''I''ll call you back'' almost never results in a call back.'),
  ('d2100007-0000-0000-0000-000000000007', 3, 'Which statement best reframes an outbound recall call as patient care rather than a sales call?', '["''We''re filling some appointments and thought you might be interested in coming in.''", "''You''ve been with us for a long time and we just want to make sure your teeth are looked after.''", "''We have some great specials on checkups at the moment if you''d like to come in.''", "''It''s been over 18 months and we think it''s important you come in soon.''"]'::jsonb, 1, 'Option B is genuinely care-focused — it references the patient relationship and their health. The other options are schedule-driven, promotional, or mildly pressuring. Patients book with practices they trust, not ones that make them feel chased.'),
  ('d2100007-0000-0000-0000-000000000007', 4, 'A patient says they''ve been thinking of trying a practice closer to their new workplace. What is the best response?', '["''That''s understandable — you can transfer your records to any practice you choose.''", "''We''re actually very accessible from most parts of Melbourne — let me tell you about our hours.''", "''I completely understand. The great thing about staying with us is that [dentist] already knows your history and what to watch for — starting fresh means losing all that context.''", "''Is there anything about your experience here we could improve? We''d love to keep you as a patient.''"]'::jsonb, 2, 'Continuity of care is SIA Dental''s strongest retention argument. Name the dentist and make their history feel valuable. This is far more compelling than competing on location or logistics.'),
  ('d2100008-0000-0000-0000-000000000008', 1, 'You call a patient who was given a crown recommendation 3 months ago and never booked. They say ''I''ve just been really busy.'' What is the best next step?', '["''No problem — shall I book you in for next week while I have you?''", "''Of course, that''s understandable. Is there anything you wanted to check or that I can help with before we get you booked in?''", "''The dentist did say it was quite urgent — it''s important we get this sorted soon.''", "''Totally fine — just give us a call when your schedule opens up.''"]'::jsonb, 1, '''Busy'' is almost always a surface-level answer. One open question — ''Is there anything you wanted to check?'' — gives the patient permission to share the real reason (fear, cost, uncertainty). Only once you know the real blocker can you address it effectively.'),
  ('d2100008-0000-0000-0000-000000000008', 2, 'A patient says they''re nervous about the crown procedure. What is the correct response?', '["''It''s really not that bad — most patients are surprised by how quick it is.''", "''I completely understand — a lot of patients feel that way. Dr [Name] is excellent at walking you through exactly what to expect, and you can stop at any time if you need a break. Most patients find it much more comfortable than they expected.''", "''The dentist will give you anaesthetic so you won''t feel anything at all.''", "''Would you like me to send you some information about the procedure first?''"]'::jsonb, 1, 'Acknowledge, normalise, then name the dentist with a specific reassurance. Vague reassurances like ''it''s not that bad'' dismiss the concern. A specific description of how the dentist handles anxious patients is far more convincing.'),
  ('d2100008-0000-0000-0000-000000000008', 3, 'How should you communicate clinical urgency without sounding like a sales pitch?', '["''You really should get this done — it''s important not to leave it too long.''", "''The dentist recommended sooner rather than later — leaving a cracked tooth can sometimes lead to needing more involved treatment down the track, and the recovery is generally easier the earlier it''s caught.''", "''If you wait much longer you might end up needing a root canal instead, which is much more expensive.''", "''It''s completely up to you — there''s no rush if you''re not ready.''"]'::jsonb, 1, 'Option B anchors urgency in the clinical recommendation and gives an honest, specific reason — not an exaggerated threat. Option C is fear-mongering. Option A is vague pressure. Option D removes all urgency and effectively invites further deferral.'),
  ('d2100008-0000-0000-0000-000000000008', 4, 'A patient had a whitening consultation 6 weeks ago and never booked. She says she''s not sure she can justify the cost. What is the best response?', '["''We do have a special on whitening at the moment — it''s a great time to book.''", "''I completely understand. Can I ask — when you came in, was there a particular reason you were thinking about whitening? Sometimes reconnecting with that goal helps.''", "''Our whitening is actually quite affordable when you consider the results — it''s professional-grade.''", "''No problem — just keep us in mind if you decide you''d like to go ahead.''"]'::jsonb, 1, 'Reconnect her to her original motivation before talking cost. When she articulates why she wanted it (confidence, an event, a goal), she reminds herself of the value — and that makes the cost feel more justified. Then you can address cost if she still raises it.'),
  ('d2100009-0000-0000-0000-000000000009', 1, 'A patient has just downloaded SIA Dental''s price guide. What does this action most likely signal?', '["They are casually browsing and are not ready to book", "They are actively researching and in the comparison phase — high intent, likely open to being helped", "They are probably a current patient who forgot our pricing", "They were referred by a friend and want to confirm prices before calling"]'::jsonb, 1, 'Downloading the price guide is a high-intent signal — they found our website, decided we were worth investigating, and shared their contact details. They are actively researching, likely comparing practices, and haven''t yet booked elsewhere. This is the ideal time to reach out.'),
  ('d2100009-0000-0000-0000-000000000009', 2, 'What is the primary goal of an outbound price guide call?', '["To explain the price guide and answer any pricing questions they have", "To convince the patient that SIA Dental is better than any practice they''ve compared", "To book an appointment — specifically a consultation so the dentist can assess them", "To qualify whether the patient is a serious lead before investing time in them"]'::jsonb, 2, 'The goal is always to get the patient into the chair for the dentist to see them. You are not selling treatment — you are selling the appointment. The dentist sells the treatment. Everything you do on the call should be aimed at securing a specific booking.'),
  ('d2100009-0000-0000-0000-000000000009', 3, 'A patient says ''I''ve already got a quote from another clinic down the road.'' What is the correct response?', '["''Can I ask what they quoted? I''m sure we can do something competitive.''", "''That''s great that you''re doing your research — though I''d check their reviews before committing.''", "''That''s really smart to compare. The thing is, a quote without a proper examination is just an estimate — every mouth is different. Our dentist can give you a personalised picture of your situation with no obligation.''", "''We always recommend coming in to us first — we''ve been in the area for years and our results speak for themselves.''"]'::jsonb, 2, 'Never compete on price or disparage competitors. Validate their research, then reframe: a quote without examination is an estimate. Your differentiator is a personalised, obligation-free consultation where the dentist assesses their specific situation. That reframe converts price-comparers far better than trying to undercut.'),
  ('d2100009-0000-0000-0000-000000000009', 4, 'A patient ticked ''Cosmetic Dentistry'' and says ''It all looks really expensive — I don''t think I can afford it.'' What is the correct approach?', '["Explain that SIA Dental''s cosmetic prices are very competitive compared to other practices", "Offer a payment plan immediately to make the cost more manageable", "Acknowledge the concern, then separate the consultation from the treatment cost: ''The consultation is just to see what''s possible for your specific situation — a lot of patients are surprised by the options. Would you be open to coming in just to see?''", "Tell them the price varies significantly depending on the treatment, so it''s worth coming in to get an accurate quote"]'::jsonb, 2, 'Don''t defend or compete on price. Separate the low-cost consultation from the full treatment cost. You are selling the appointment, not the treatment. ''Come in to see what''s possible'' removes the financial risk of the next step and gets the patient in front of the dentist, where the real conversion happens.'),
  ('d2100010-0000-0000-0000-000000000010', 1, 'Before making an OTP follow-up call, what is the FIRST thing you should do?', '["Check the patient''s phone number is still current in the system", "Open the patient file in D4W and confirm the dentist, treatment recommended, and health fund on file", "Prepare a script for the call so you don''t forget any key information", "Check whether the appointment slot is available before calling"]'::jsonb, 1, 'The preparation ritual is non-negotiable. You need the dentist''s name, the exact treatment, and the health fund before you dial. Walking in blind means you lose credibility the moment the patient asks a specific question. The other steps can happen, but the file review comes first.'),
  ('d2100010-0000-0000-0000-000000000010', 2, 'You call a patient about a recommended crown. They say ''I''ve just been really busy.'' What is the correct next step?', '["''No problem — shall I just book you in for Tuesday at 11?''", "''Of course — is there anything you wanted to check or that I can help with before we get you booked in?''", "''I understand — Dr Kwong did say this was quite important, so we really should get it sorted soon.''", "''Totally fine — just give us a call when your schedule opens up.''"]'::jsonb, 1, '''Busy'' is almost always a surface answer. The open question — ''Is there anything you wanted to check?'' — gives the patient permission to name the real blocker without embarrassment. Only once you know the actual concern can you address it effectively. Option C jumps to pressure before diagnosing the problem. Option D loses the call entirely.'),
  ('d2100010-0000-0000-0000-000000000010', 3, 'A patient had a cosmetic veneer consultation 10 weeks ago and never followed up. She says she''s not sure she can justify the cost. What should you NOT do?', '["Ask what originally motivated her to look into veneers in the first place", "Tell her that cosmetic work like this is usually covered partially by health funds", "Reconnect her to her original motivation before discussing cost", "Offer a low-commitment follow-up consultation as the next step"]'::jsonb, 1, 'Cosmetic dental work (veneers, whitening, smile makeovers) is NOT covered by health funds — telling a patient otherwise is inaccurate and will destroy trust when they find out. For cosmetic OTP calls, the right approach is reconnecting to motivation, addressing the specific concern (fear, uncertainty, timing), and offering a low-commitment next step.'),
  ('d2100010-0000-0000-0000-000000000010', 4, 'After three genuine attempts, a patient still won''t commit to booking their root canal appointment. What is the minimum acceptable outcome before ending the call?', '["Thank them warmly and tell them to call back when they are ready", "Add them to the recall list and flag for a follow-up next month", "Book a specific follow-up call in 2 weeks — a named day and time — and log it in D4W", "Escalate to the practice manager to follow up directly"]'::jsonb, 2, 'The 2-week rule: every OTP patient either has a booking or a specific named follow-up date. ''Call back when ready'' means the patient is lost. A recall list without a committed call date is nearly as bad. The correct outcome is a specific, agreed follow-up: ''Can I call you Thursday the 19th at 10am?'' — then log it in D4W before you move on.'),
  ('d2100011-0000-0000-0000-000000000011', 1, 'You''re calling a patient whose 6-month recall was booked with a dentist who has now left. What is the WORST thing you can do?', '["Acknowledge they''ve always seen the departing dentist before pivoting", "Offer to cancel the appointment and let them call back when they''re ready", "Endorse the new dentist with a specific, warm description", "Reassure them their records and history carry across to the new dentist"]'::jsonb, 1, 'Offering to cancel hands a hesitant patient the exit — they''ll take it and won''t call back. On a handover call you assume continuity: the appointment stands, just with a great new dentist. Acknowledging, endorsing, and reassuring continuity are all exactly what you SHOULD do.'),
  ('d2100011-0000-0000-0000-000000000011', 2, 'A loyal patient says ''But I''ve always seen Dr Low.'' What is the strongest response?', '["''I understand — one of our other dentists can see you instead, no problem.''", "''I know, and you''ve been in great hands with her. The good news is your full history carries straight across, and Dr Ong who''s taken over her patients is lovely — very gentle and takes her time. People who were nervous about the change have been really happy with her.''", "''Unfortunately Dr Webb has left, so you''ll need to see someone else now.''", "''Would you prefer to wait and see if he comes back at some point?''"]'::jsonb, 1, 'A real endorsement acknowledges the relationship, reassures continuity (history carries across), and endorses the new dentist with specifics. ''Someone else can see you'' is a cold substitution. ''You''ll need to see someone else'' makes them a problem being reassigned. Option D invites them to defer indefinitely on a dentist who isn''t returning.'),
  ('d2100011-0000-0000-0000-000000000011', 3, 'A patient with an open treatment plan says ''I''d talked all that through with Dr Hartley — I''d rather just wait for him.'' Dr Hartley has left the practice and is not returning. What is the correct approach?', '["Agree to wait and tell them to call back if Dr Hartley returns", "Tell them Dr Hartley isn''t coming back, so they have no choice but to see someone new", "Gently let them know Dr Hartley has moved on, then reassure them the new dentist already has the full plan, notes and X-rays and continues exactly where things were left — no starting over", "Suggest they come in for a fresh examination with the new dentist to reassess everything"]'::jsonb, 2, 'Waiting for a dentist who isn''t returning guarantees the patient drifts away — never let that stand. The key fear with a treatment plan is starting from scratch, so the winning reassurance is continuity: the new dentist has the existing plan, notes and X-rays, with no re-examination and no paying twice. Option D triggers exactly the ''start all over again'' fear you need to remove.'),
  ('d2100011-0000-0000-0000-000000000011', 4, 'A patient asks why their dentist left. What is the best way to handle it?', '["Explain the full background so the patient feels informed and respected", "Keep it simple, positive and private — ''Dr [X] has moved on from the practice'' — then redirect to continuity and the new dentist", "Admit you''re not really sure why they left and offer to find out", "Reassure them the departing dentist''s leaving had nothing to do with the practice"]'::jsonb, 1, 'The reason a dentist left is private and rarely helps the patient. A simple, positive ''has moved on from the practice'' is enough — then steer the conversation back to what matters to the patient: their history and records are safe, and there''s a great new dentist ready to look after them. Speculating, gossiping, or getting defensive all undermine confidence.'),
  ('d2100012-0000-0000-0000-000000000012', 1, 'You''re reactivating a patient who hasn''t been in for years and doesn''t recognise the practice''s name. What does the opening of the call most need to do?', '["Get straight to the point and offer them a discounted check-up to grab their attention", "Clearly and warmly establish who you are, which practice, why you''re calling, and why it''s relevant to them — before anything else", "Ask them to confirm their date of birth and address so you can update the records", "Mention that they''re overdue for a check-up, just like you would on a normal recall"]'::jsonb, 1, 'On a cold-trust call the patient doesn''t recognise you, so the opening must answer four unspoken questions immediately — who, which practice, why calling, why care. Leading with an offer (A) sounds like a telemarketer; admin questions (C) feel intrusive before trust exists; and ''you''re overdue'' (D) assumes a relationship the patient hasn''t yet accepted.'),
  ('d2100012-0000-0000-0000-000000000012', 2, 'A patient asks ''What happened to the old place? Is Dr Smith still there?'' How should you handle it?', '["Explain in detail why the previous owner sold and what was going wrong before", "Say you''re not really sure about the history and offer to find out for them", "Be straightforward and positive but brief — the practice came under new ownership, the new team has reinvested — and never criticise the previous owner", "Avoid the question and steer straight back to booking an appointment"]'::jsonb, 2, 'Transparency wins trust, but keep it simple and positive — and never bad-mouth the previous owner, even if the patient left unhappy. Over-explaining the sale (A) is unnecessary and risks negativity; vagueness (B) and dodging (D) both make a wary patient more suspicious, not less.'),
  ('d2100012-0000-0000-0000-000000000012', 3, 'A patient says ''I stopped going there for a reason — it went downhill and I wasn''t happy.'' What is the best response?', '["''I''m sure it wasn''t that bad — we''ve always had really good dentists here.''", "''I''m really sorry that was your experience — that''s exactly what the new team is determined to put right. The new owners have reinvested and we spend more time with each patient now. I''d love the chance to show you it''s genuinely different — even just a check-up to start fresh.''", "''That was the previous owner — they really let the place go before they sold it.''", "''No problem, I understand — I''ll take you off our list so we don''t bother you again.''"]'::jsonb, 1, 'Acknowledge genuinely without defensiveness, then differentiate the new ownership as a real, concrete change, then make a low-pressure invitation. Defending the old practice (A) confirms her fear nothing changed; bad-mouthing the previous owner (C) looks unprofessional; and removing her (D) throws away a winnable patient instead of giving her a reason to return.'),
  ('d2100012-0000-0000-0000-000000000012', 4, 'A patient had a treatment plan started two years ago by a dentist who has since left, and the records are thin. He says he doesn''t even remember what it was for. What is the correct approach?', '["Read out the old plan confidently as if it''s still exactly current and book that treatment", "Tell him it''s probably not important anymore and just book a routine clean", "Be honest that some work was started but never finished, that the dentist who saw him has moved on, and that the sensible next step is a fresh comprehensive assessment with no obligation", "Suggest he find his old paperwork and call back once he remembers the details"]'::jsonb, 2, 'With limited continuity, honesty is the strategy: reconnect him to the unfinished treatment, be upfront that a fresh assessment is the right reset, and get him back in the chair. Pretending the old plan is fully current (A) gets exposed the moment he asks a detail; dismissing it (B) wastes a real clinical need; and putting the work on him (D) loses the patient.');
